using System;using System.Linq;using System.Text;using System.IO;using Verse;using PlayableRecreation;using PRQA;
public static class Command{public static string Run(){var m=Find.CurrentMap;Host.State["map"]=m;foreach(var k in new[]{"rostra","anya","guest","ineligible"}){string name=k=="rostra"?"Rostra":k=="anya"?"Anya":k=="guest"?"QA Visitor":"QA Ineligible";Host.State[k]=m.mapPawns.AllPawnsSpawned.First(p=>p.LabelShort==name);}Host.State["chess"]=m.listerThings.AllThings.First(t=>t.ThingID=="ChessTable66193");var s=new StringBuilder();s.AppendLine("after-load "+TogetherMatch.Describe()+"\n"+TogetherInvite.Describe());foreach(var b in m.listerThings.AllThings.Where(t=>t.TryGetComp<CompMiniGame>()!=null)){var session=GameComponent_Recreation.Current.SessionFor(b);if(session!=null)s.AppendLine("stored="+b+" game="+session.game+" rounds="+session.rounds+" tier="+session.tier+" seated="+session.seatedPawn+" currentPawn="+m.mapPawns.AllPawnsSpawned.Contains(session.seatedPawn));}var g=(Pawn)Host.State["guest"];s.AppendLine("guestBeforeTicks="+g.CurJobDef);int start=Find.TickManager.TicksGame;Host.Watch=()=>{int t=Find.TickManager.TicksGame;if(t-start>=150){File.WriteAllText(Host.Root+"/after-load-guest.txt","elapsed="+(t-start)+" guest="+g.CurJobDef+" waiting="+TogetherInvite.IsWaiting(g));Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return s.ToString();}}
